 const playWord=(word:string)=>{const fallback=()=>{if(typeof speechSynthesis==="undefined")return;const voices=speechSynthesis.getVoices().filter(v=>/^en(?:-|$)/i.test(v.lang)),voice=voices.find(v=>/^en-US/i.test(v.lang))??voices.find(v=>/^en-GB/i.test(v.lang))??voices[0];if(!voice)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word);utterance.voice=voice;utterance.lang=voice.lang;utterance.rate=.85;speechSynthesis.speak(utterance)};const audio=new Audio(`${import.meta.env.BASE_URL}audio/words/${audioSlug(word)}.wav`);audio.onerror=fallback;void audio.play().catch(fallback)};
 const clear=()=>{stopActiveAudio?.();setItem(0);setInput("");setChecked(null);setAnswered(null);setSpoken("");setDictation("");setDictationChecked(false)};
