 const analyzeWriting=()=>{const t=writing.trim(),notes:string[]=[];let corrected=t;const fix=(pattern:RegExp,replacement:string,note:string)=>{if(pattern.test(corrected)){corrected=corrected.replace(pattern,replacement);notes.push(note)}};if(t&&!/^[A-Z]/.test(t)){corrected=corrected.charAt(0).toUpperCase()+corrected.slice(1);notes.push("La frase inglese inizia con la maiuscola.")}if(t&&!/[.!?]$/.test(t)){corrected+=".";notes.push("Ho aggiunto la punteggiatura finale.")}fix(/\bI am agree\b/gi,"I agree","Agree è un verbo: si dice I agree, senza am.");fix(/\bpeople is\b/gi,"people are","People è plurale e richiede are.");fix(/\bI have (\d+) years(?: old)?\b/gi,"I am $1 years old","Per l'età l'inglese usa be: I am ... years old.");fix(/\binformations\b/gi,"information","Information è non numerabile e non prende -s.");fix(/\bdepend of\b/gi,"depend on","La collocazione corretta è depend on.");fix(/\bmarried with\b/gi,"married to","La collocazione corretta è married to.");fix(/\bsince (\d+) years\b/gi,"for $1 years","Usa for con una durata; since introduce il punto iniziale.");fix(/\ba ([aeiou]\w*)\b/gi,"an $1","Davanti a un suono vocalico usa normalmente an.");const third=/\b(he|she|it)\s+(work|live|speak|need|want|like|start|finish)\b/gi;if(third.test(corrected)){corrected=corrected.replace(third,(_,subject,verb)=>`${subject} ${verb}${verb.endsWith("s")?"":"s"}`);notes.push("Con he, she o it il Present Simple richiede normalmente -s.")}const past:Record<string,string>={went:"go",saw:"see",took:"take",came:"come",had:"have",did:"do"};const didPast=/\bdid\s+(went|saw|took|came|had|did)\b/gi;if(didPast.test(corrected)){corrected=corrected.replace(didPast,(_,verb)=>`did ${past[String(verb).toLowerCase()]}`);notes.push("Dopo did usa il verbo base, non la forma passata.")}const target=unit.grammar.formulas[0]?.trim();if(target&&!notes.length)notes.push(`Non vedo errori tra quelli controllabili offline. Struttura da confrontare: ${target}`);setWritingSuggestion(corrected);setWritingNotes(notes)};
 const record=async()=>{const R=window.SpeechRecognition??window.webkitSpeechRecognition;if(!R){setSpoken("Il riconoscimento vocale non è supportato qui. Apri il link con Chrome o Edge.");return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(track=>track.stop())}catch{setSpoken("Permesso microfono negato. Abilitalo nelle impostazioni del browser.");return}const r=new R();r.lang="en-US";r.interimResults=true;r.continuous=false;r.maxAlternatives=3;let heard=false;const timeout=window.setTimeout(()=>{try{r.stop()}catch{}},12000);r.onresult=e=>{const candidates:string[]=[];for(let i=0;i<e.results.length;i++){const result=e.results[i];for(let j=0;j<result.length;j++)if(result[j]?.transcript)candidates.push(result[j].transcript)}if(candidates.length){heard=true;const best=candidates.sort((a,b)=>similarity(unit.speaking.target,b)-similarity(unit.speaking.target,a))[0];setSpoken(best)}};r.onerror=e=>{window.clearTimeout(timeout);heard=true;const messages:Record<string,string>={"not-allowed":"Permesso microfono negato.","no-speech":"Non ho sentito la voce. Avvicinati al microfono e riprova.","audio-capture":"Microfono non disponibile.",network:"Il servizio vocale del browser non è raggiungibile."};setSpoken(messages[e.error]??"Non ho riconosciuto bene la frase. Riprova più lentamente.");setRecording(false)};r.onnomatch=()=>{heard=true;setSpoken("Ho sentito la voce, ma non ho riconosciuto le parole. Riprova lentamente.")};r.onspeechend=()=>{try{r.stop()}catch{}};r.onend=()=>{window.clearTimeout(timeout);setRecording(false);if(!heard)setSpoken("Non ho ricevuto una trascrizione. Riprova con Chrome o Edge e parla dopo il segnale.")};setSpoken("");setRecording(true);r.start()};
 const resetAllProgress=async()=>{const clean=fresh(deviceId());localStorage.removeItem("english-coach-checkpoints-v1");localStorage.removeItem("english-coach-selection-v1");setSelectedLevel("A1");setSelectedLessonId(mobileCurriculum[0].id);setProgress(clean);await save(clean);setResetConfirm(false);setView("home");scrollTo(0,0)}; const recoverProgress=async()=>{if(!validCode(recover)){setRecoverMsg("Il codice non sembra completo. Copialo nuovamente senza spazi.");return}try{const imported=decodeProgress(recover),restored={...fresh(deviceId()),...imported,deviceId:deviceId(),schemaVersion:4};setProgress(restored);await save(restored);setRecover("");setRecoverMsg("Backup ripristinato correttamente su questo dispositivo.")}catch{setRecoverMsg("Non riesco a leggere questo backup. Verifica di aver copiato tutto il codice.")}};
